-- Baseline schema for a genuinely empty Postgres volume.
--
-- Every other file in this directory is an incremental ALTER TABLE/ADD
-- COLUMN migration that assumes its base tables already exist — true until
-- now only via TypeORM's dev-mode `synchronize: true`. This file creates
-- every TypeORM-entity-backed table from scratch, generated by running the
-- real API once with synchronize enabled against an empty database and
-- dumping the resulting schema — not hand-written — so it exactly matches
-- current entity definitions. Runs first (00000000 sorts before every other
-- migration's date prefix), so a fresh server no longer needs a manual
-- bootstrap step before `api` can start.
--
-- Tables with no TypeORM @Entity() class (e.g. qa_service_status_incidents)
-- are intentionally absent here — those are still created by their own
-- incremental migration further down the chain.

BEGIN;

--
-- Name: uuid-ossp; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA public;


--
-- Name: EXTENSION "uuid-ossp"; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION "uuid-ossp" IS 'generate universally unique identifiers (UUIDs)';


--
-- Name: vector; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;


--
-- Name: EXTENSION vector; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION vector IS 'vector data type and ivfflat and hnsw access methods';


-- cosine_similarity() is NOT dumped here — it's infra set up by
-- init-db/01-init.sql (which also creates the vector extension above, via
-- Postgres' own docker-entrypoint-initdb.d, before this file ever runs),
-- not a TypeORM-entity-backed object. Redefining it here would collide with
-- that earlier CREATE FUNCTION (no OR REPLACE in a plain pg_dump).

SET default_table_access_method = heap;

--
-- Name: agent_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_sessions (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    "agentType" character varying(10) NOT NULL,
